<script setup>
import TicketScanner from '../../Components/Shared/TicketScanner.vue';
import { computed, ref } from 'vue';
import { Link, router, useForm } from '@inertiajs/vue3';
import { Plus, Search, Compass, CalendarDays, ArrowUpRight, Trash2 } from 'lucide-vue-next';
import { route } from 'ziggy-js';
import PanelLayout from '../../Components/Admin/PanelLayout.vue';
import Pagination from '../../Components/Admin/Pagination.vue';
const props = defineProps({ section: String, vendor: Object, records: Object, stats: Array, filters: Object, tripCounts: Object });
const search = ref(props.filters?.search || '');
const labels = { draft: 'Draf', pending: 'Dalam peninjauan', published: 'Terbit', rejected: 'Ditolak', archived: 'Diarsipkan' };
const filterTrips = (status = props.filters?.status || '') => router.get(route('vendor.section', 'trips'), { search: search.value, status }, { preserveState: true, preserveScroll: true });
const date = value => value ? new Date(value).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' }) : '—';
const sections = { trips: 'Trip & Jadwal', bookings: 'Pemesanan', finance: 'Keuangan', reviews: 'Rating & Ulasan', profile: 'Profil & Verifikasi', support: 'Bantuan & Chat' };
const navigation = Object.entries(sections).map(([key, label]) => ({ key, label, group: ['profile', 'support'].includes(key) ? 'Bisnis Anda' : 'Operasional', url: route('vendor.section', key) }));
navigation.push({ key: 'souvenirs', label: 'Produk & pesanan oleh-oleh', group: 'Operasional', url: route('vendor.souvenirs') });
const form = useForm({ name: props.vendor?.name || '', city: props.vendor?.city || '', email: props.vendor?.email || '', phone: props.vendor?.phone || '', description: props.vendor?.description || '', document_id: props.vendor?.document_id || '' });
const upload = useForm({ file: null, alt_text: 'Dokumen verifikasi mitra', visibility: 'private' });
const statusForm = useForm({ status: '' });
const documentName = computed(() => form.document_id ? 'Dokumen sudah dipilih' : 'Belum ada dokumen');
function uploadDocument() { upload.post(route('media.store'), { onSuccess: page => { const media = page.props.flash?.uploaded_media; if (media?.visibility === 'private') { form.document_id = media.id; upload.reset(); } } }); }
const money = n => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
const transition = (item, status) => { statusForm.status = status; statusForm.put(route('vendor.bookings.update', item.id)); };
const deletingTripId = ref(null);
function deleteTrip(item) {
    if (!confirm(`Hapus trip "${item.title}"? Trip yang dihapus tidak akan tampil lagi di katalog.`)) {
        return;
    }
    deletingTripId.value = item.id;
    router.delete(route('vendor.trips.destroy', item.id), {
        preserveScroll: true,
        onFinish: () => {
            deletingTripId.value = null;
        },
    });
}
</script>
<template>
    <PanelLayout :title="sections[section] || 'Overview Partner'" subtitle="Kelola perjalanan dan layanan lokal, dari satu workspace." :navigation="navigation" vendor>
        <TicketScanner v-if="section === 'bookings' && vendor?.status === 'verified'" /><template #actions><Link v-if="section === 'trips' && vendor?.status === 'verified'" :href="route('vendor.trips.create')" class="panel-primary">Tambah trip / jadwal</Link></template>
        <div v-if="!vendor || vendor.status !== 'verified'" class="mb-6 rounded-xl border border-amber-100 bg-amber-50 p-4 text-sm leading-6 text-amber-800">Status mitra: <strong>{{ vendor?.status || 'belum terdaftar' }}</strong>. Lengkapi profil dan dokumen agar tim operasional dapat meninjau bisnis kamu.</div>
        <template v-if="section === 'profile' || !vendor"><p v-for="(error,key) in form.errors" :key="key" role="alert" class="mb-3 text-sm text-red-700">{{ error }}</p><p v-for="(error,key) in upload.errors" :key="key" role="alert" class="mb-3 text-sm text-red-700">{{ error }}</p>
            <form class="panel-surface max-w-3xl p-6" @submit.prevent="form.put(route('vendor.profile.save'))"><h2 class="mb-5 font-bold">Identitas bisnis</h2><div class="grid gap-4 sm:grid-cols-2"><label v-for="(label, key) in { name: 'Nama bisnis', city: 'Kota', email: 'Email bisnis', phone: 'Nomor kontak' }" :key="key" class="text-xs font-semibold">{{ label }}<input v-model="form[key]" :type="key === 'email' ? 'email' : key === 'document_id' ? 'number' : 'text'" :required="key !== 'document_id'" class="panel-input mt-2" /></label><label class="text-xs font-semibold sm:col-span-2">Deskripsi<textarea v-model="form.description" rows="4" class="panel-input mt-2"></textarea></label></div><button :disabled="form.processing" class="panel-primary mt-5">Simpan profil</button></form>
            <form class="panel-surface mt-5 max-w-3xl p-6" @submit.prevent="uploadDocument"><h2 class="text-sm font-bold">Dokumen verifikasi privat</h2><p class="mt-2 text-sm">{{ documentName }}</p><p class="mt-2 text-xs leading-6 text-slate-500">Upload JPG, PNG, WebP atau PDF maksimal 5 MB. Setelah upload, simpan profil untuk mengajukan verifikasi.</p><input required type="file" class="mt-4 block text-xs" accept="image/jpeg,image/png,image/webp,application/pdf" @change="upload.file = $event.target.files[0]" /><button :disabled="upload.processing" class="panel-secondary mt-4">Upload dokumen</button></form>
        </template>
        <template v-else-if="section === 'dashboard'"><div class="grid gap-4 sm:grid-cols-3"><article v-for="stat in stats" :key="stat.label" class="panel-surface p-6"><p class="text-xs text-slate-500">{{ stat.label }}</p><p class="mt-4 text-3xl font-bold">{{ stat.money ? money(stat.value) : stat.value }}</p></article></div><div class="panel-surface mt-6 p-7"><h2 class="text-lg font-bold">Siapkan perjalanan berikutnya.</h2><p class="mt-2 max-w-xl text-sm leading-7 text-slate-500">Periksa jadwal, kuota, dan pesanan. Trip yang diajukan akan ditinjau tim Tapak Lokal sebelum terbit.</p><Link :href="route('vendor.section', 'trips')" class="panel-primary mt-5">Kelola trip</Link></div></template>
        <template v-else-if="section === 'trips'">
            <div class="mb-6 grid grid-cols-2 gap-4 xl:grid-cols-4">
                <button v-for="(label, key) in { all: 'Total trip', published: 'Trip terbit', pending: 'Dalam peninjauan', draft: 'Draf trip' }" :key="key" class="rounded-xl border border-slate-200 bg-white p-5 text-left transition hover:border-blue-400" @click="filterTrips(key === 'all' ? '' : key)">
                    <p class="text-sm text-slate-500">{{ label }}</p><p class="mt-3 text-3xl font-semibold tracking-tight text-[#103b60]">{{ key === 'all' ? Object.values(tripCounts || {}).reduce((sum, n) => sum + Number(n), 0) : tripCounts?.[key] || 0 }}</p>
                </button>
            </div>
            <section class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
                <div class="flex flex-wrap items-center justify-between gap-4 px-6 pt-6"><div><h2 class="text-lg font-bold text-[#103b60]">Daftar perjalanan</h2><p class="mt-1 text-sm text-slate-500">Kelola penawaran dan pantau peninjauan trip Anda.</p></div><form class="flex w-full items-center gap-2 rounded-lg border border-slate-200 px-3 sm:w-80" @submit.prevent="filterTrips()"><Search class="size-4 text-slate-400" /><input v-model="search" aria-label="Cari trip atau destinasi" placeholder="Cari trip atau destinasi" class="min-w-0 flex-1 bg-transparent py-3 text-sm outline-none" /><button class="text-sm font-semibold text-blue-600">Cari</button></form></div>
                <div class="mt-5 flex gap-6 overflow-x-auto border-b border-slate-200 px-6"><button v-for="(label, key) in { '': 'Semua trip', ...labels }" :key="key" class="shrink-0 border-b-2 pb-4 text-sm font-semibold transition" :class="(filters?.status || '') === key ? 'border-[#078cff] text-[#078cff]' : 'border-transparent text-slate-500 hover:text-blue-600'" @click="filterTrips(key)">{{ label }}</button></div>
                <div v-if="records?.data?.length" class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="px-6 py-4">Trip & destinasi</th><th class="p-4">Keberangkatan</th><th class="p-4">Harga / peserta</th><th class="p-4">Status</th><th class="p-4">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in records.data" :key="item.id" class="hover:bg-blue-50/30"><td class="px-6 py-5"><div class="flex items-center gap-3"><img v-if="item.image_url" :src="item.image_url" alt="" class="size-16 rounded-lg object-cover" /><span v-else class="grid size-16 shrink-0 place-items-center rounded-lg bg-blue-50 text-blue-500"><Compass class="size-7" /></span><div><Link :href="route('vendor.trips.edit', item.id)" class="font-semibold text-[#103b60] hover:text-blue-600">{{ item.title }}</Link><p class="mt-1.5 text-xs text-slate-500">{{ item.destination }}</p></div></div></td><td class="p-4"><p>{{ date(item.departure_date) }}</p><p class="mt-1 text-xs text-slate-500">Kuota {{ item.capacity }} peserta</p></td><td class="p-4 font-semibold">{{ money(item.price) }}</td><td class="p-4"><span class="inline-flex rounded-md px-2.5 py-1 text-xs font-semibold" :class="item.status === 'published' ? 'bg-emerald-50 text-emerald-700' : item.status === 'pending' ? 'bg-amber-50 text-amber-700' : item.status === 'rejected' ? 'bg-rose-50 text-rose-700' : 'bg-slate-100 text-slate-600'">{{ labels[item.status] || item.status }}</span></td><td class="p-4"><div class="flex items-center gap-3"><Link :href="route('vendor.trips.edit', item.id)" class="inline-flex items-center gap-1 font-semibold text-blue-600 hover:text-blue-700">Kelola <ArrowUpRight class="size-4" /></Link><button type="button" :disabled="deletingTripId === item.id" class="inline-flex items-center gap-1 text-xs font-semibold text-rose-600 hover:text-rose-700 hover:underline transition disabled:opacity-40" title="Hapus trip ini" @click="deleteTrip(item)"><Trash2 class="size-3.5" /><span>{{ deletingTripId === item.id ? 'Menghapus…' : 'Hapus' }}</span></button></div></td></tr></tbody></table></div>
                <div v-else class="flex flex-col items-center px-6 py-14 text-center"><span class="mb-5 grid size-20 place-items-center rounded-full bg-[#eef7ff] text-[#078cff]"><CalendarDays class="size-9" stroke-width="1.4" /></span><h3 class="text-lg font-bold text-[#103b60]">{{ filters?.search || filters?.status ? 'Trip tidak ditemukan' : 'Perjalanan pertama dimulai di sini' }}</h3><p class="mt-2 max-w-md text-sm leading-6 text-slate-500">{{ filters?.search || filters?.status ? 'Coba kata kunci lain atau tampilkan semua status trip.' : 'Tambahkan destinasi, jadwal, dan harga perjalanan. Kirim ke admin untuk ditinjau sebelum tampil di TapakLokal.' }}</p><Link v-if="vendor?.status === 'verified' && !filters?.search && !filters?.status" :href="route('vendor.trips.create')" class="panel-primary mt-6"><Plus class="size-4" /> Buat trip pertama</Link><button v-else-if="filters?.search || filters?.status" class="panel-secondary mt-6" @click="search = ''; filterTrips('')">Reset pencarian</button></div>
                <Pagination :records="records" />
            </section>
            <p class="mt-5 rounded-xl border border-blue-100 bg-blue-50/60 p-4 text-sm leading-6 text-[#365979]"><strong>Publikasi melalui peninjauan admin.</strong> Simpan draf untuk melanjutkan nanti, atau kirim pengajuan agar admin operasional memeriksa trip Anda.</p>
        </template>
        <section v-else class="panel-surface"><p v-for="(error,key) in statusForm.errors" :key="key" role="alert" class="p-5 text-sm text-red-700">{{ error }}</p>
            <article v-for="item in records?.data || []" :key="item.id" class="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 p-5">
                <div class="min-w-0"><p class="text-sm font-bold">{{ item.title || item.reference || item.subject || item.trip?.title || 'Payout #' + item.id }}</p><p class="mt-2 text-xs text-slate-500">{{ item.destination || item.contact_name || item.body || '' }}</p><p class="mt-2 text-xs text-slate-400">{{ item.departure_date?.slice(0, 10) || '' }} {{ item.status }}</p><p v-if="item.corporate_request" class="mt-2 text-xs font-semibold text-blue-700">Corporate · {{ item.corporate_request.company.name }}</p><details v-if="section==='bookings'" class="mt-3 text-xs"><summary class="cursor-pointer font-semibold">Kontak, kebutuhan & peserta</summary><p class="mt-3">{{ item.contact_name }} · {{ item.contact_phone }} · {{ item.contact_email }}</p><p class="mt-2 whitespace-pre-line leading-6">{{ item.special_request }}</p><ol class="mt-3 list-inside list-decimal space-y-2"><li v-for="(person,index) in item.traveler_details" :key="index">{{ person.name }}</li></ol></details><p v-if="item.total || item.amount || item.price" class="mt-2 text-sm font-semibold text-blue-600">{{ money(item.total || item.amount || item.price) }}</p></div>
                <div class="flex flex-wrap items-center gap-2"><Link v-if="section === 'trips'" :href="route('vendor.trips.edit', item.id)" class="panel-secondary">Kelola</Link><button v-if="section === 'trips'" type="button" :disabled="deletingTripId === item.id" class="inline-flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-xs font-semibold text-rose-600 hover:bg-rose-50 transition disabled:opacity-40" @click="deleteTrip(item)"><Trash2 class="size-3.5" />{{ deletingTripId === item.id ? 'Menghapus…' : 'Hapus' }}</button><Link v-if="section === 'support'" :href="route('support.show', item.id)" class="panel-secondary">Buka chat</Link><template v-if="section === 'bookings'"><button v-if="item.status === 'paid'" class="panel-primary" :disabled="statusForm.processing" @click="transition(item, 'confirmed')">Konfirmasi</button><button v-if="item.status === 'confirmed'" class="panel-secondary" :disabled="statusForm.processing" @click="transition(item, 'ongoing')">Mulai</button><button v-if="item.status === 'ongoing'" class="panel-secondary" :disabled="statusForm.processing" @click="transition(item, 'completed')">Selesai</button></template></div>
            </article>
            <p v-if="!records?.data?.length" class="p-16 text-center text-sm text-slate-400">Belum ada data untuk bagian ini.</p><Pagination :records="records" />
        </section>
        <p v-if="section === 'finance'" class="mt-4 text-xs text-slate-500">Payout dibuat setelah perjalanan selesai. Persetujuan dan pengiriman dana memiliki status terpisah.</p>
    </PanelLayout>
</template>
